export function getAllTours(): TourData[] {
  return TOURS_DATA;
}

export function getTourBySlug(slug: string): TourData | undefined {
  if (!slug) return undefined;
  const cleanSlug = slug.toLowerCase().trim();
  return TOURS_DATA.find(
    (t) => t.slug === cleanSlug || t.aliases.some((a) => a.toLowerCase() === cleanSlug)
  );
}

export function getFeaturedTours(): TourData[] {
  return TOURS_DATA.filter((t) => t.badge).slice(0, 6);
}

export function getToursByCategory(category: string): TourData[] {
  if (!category || category === 'all') return TOURS_DATA;
  return TOURS_DATA.filter((t) => t.category === category || t.slug.includes(category));
}
